-- Demo company fake data — HR & Housekeeping
-- Generated for demo/sales purposes. Run in the Supabase SQL editor.
-- ~18 employees across departments, uniform + linen stock (one item each
-- deliberately low), work schedule rotation, leave, and two Fixed-term
-- contracts ending within 40 days to show the Contracts Ending Soon alert.






















-- Verification:
select 'hr_employees' as t, count(*) from hr_employees where company_id = (select id from companies where slug='demo')
union all select 'hr_contracts', count(*) from hr_contracts where company_id = (select id from companies where slug='demo')
union all select 'hr_linen_movements', count(*) from hr_linen_movements where company_id = (select id from companies where slug='demo');
